uint32_t time()
{
  uint32_t cycles;
  asm volatile("rdcycle %0" : "=r"(cycles));
  asm volatile("rdcycleh %0" : "=r"(cycles));
  // printf("[time() -> %d]", cycles);
  return cycles;
}

uint32_t insn()
{
  uint32_t insns;
  asm volatile("rdinstret %0" : "=r"(insns));
  asm volatile("rdinstreth %0" : "=r"(insns));
  // printf("[insn() -> %d]", insns);
  return insns;
}

