//PDSCHDag2_hw_2p0
  push_fifo(&pdsch_config_s.fifo, (int)&pdsch_config);
  push_fifo(&carrier_s.fifo, (int)&carrier);
  push_fifo(&rxData_real_shuffle_s.fifo, (int)&output_rxData_real_excepted);
  push_fifo(&rxData_imag_shuffle_s.fifo, (int)&output_rxData_imag_excepted);

  fire_dag(PDSCHDag2_hw_2p0, 4, 7, &pdsch_config_s, &carrier_s, &rxData_real_shuffle_s, &rxData_imag_shuffle_s,
    &h_real_s, &h_imag_s, &demod_s, &demod_length_s, &seq2tmp_s, &tbs_s, &pdsch_llr);
  fire_dag_fence();

  REG_WRITE(0x1fff4000 + 0x0, 0x4); // gpio2 pluse, dag1 complete
  REG_WRITE(0x1fff4000 + 0x0, 0x0); // gpio2 pluse

  unsigned char* output_h_real_data = (unsigned char*)pop_fifo(&h_real_s.fifo);
  for (int i = 0; i < 7488; i++) {
    if (output_h_real_data[i] != (unsigned char)output_h_real_excepted[i]) {
      printf("ERROR: output_h_real[%d] = %d, expected %d\n", i, output_h_real_data[i], (unsigned char)output_h_real_excepted[i]);
      REG_WRITE(0x1fff4000 + 0x0, 0x18); // gpio3 4 pluse
      REG_WRITE(0x1fff4000 + 0x0, 0x0); // gpio3 4 pluse
    }
  }
  unsigned char* output_h_imag_data = (unsigned char*)pop_fifo(&h_imag_s.fifo);
  for (int i = 0; i < 7488; i++) {
    if (output_h_imag_data[i] != (unsigned char)output_h_imag_excepted[i]) {
      printf("ERROR: output_h_imag[%d] = %d, expected %d\n", i, output_h_imag_data[i], (unsigned char)output_h_imag_excepted[i]);
      REG_WRITE(0x1fff4000 + 0x0, 0x18); // gpio3 4 pluse
      REG_WRITE(0x1fff4000 + 0x0, 0x0); // gpio3 4 pluse
    }
  }
  unsigned char* output_demod_data = (unsigned char*)pop_fifo(&demod_s.fifo);
  for (int i = 0; i < 4; i++) {
    if (output_demod_data[i] != (unsigned char)output_demod_excepted[i]) {
      printf("ERROR: output_demod[%d] = %d, expected %d\n", i, output_demod_data[i], (unsigned char)output_demod_excepted[i]);
      REG_WRITE(0x1fff4000 + 0x0, 0x18); // gpio3 4 pluse
      REG_WRITE(0x1fff4000 + 0x0, 0x0); // gpio3 4 pluse
    }
  }
  unsigned char* output_demod_length_data = (unsigned char*)pop_fifo(&demod_length_s.fifo);
  for (int i = 0; i < 2; i++) {
    if (output_demod_length_data[i] != (unsigned char)output_demod_length_excepted[i]) {
      printf("ERROR: output_demod_length[%d] = %d, expected %d\n", i, output_demod_length_data[i], (unsigned char)output_demod_length_excepted[i]);
      REG_WRITE(0x1fff4000 + 0x0, 0x18); // gpio3 4 pluse
      REG_WRITE(0x1fff4000 + 0x0, 0x0); // gpio3 4 pluse
    }
  }
  unsigned char* output_seq2tmp_data = (unsigned char*)pop_fifo(&seq2tmp_s.fifo);
  for (int i = 0; i < 31; i++) {
    if (output_seq2tmp_data[i] != (unsigned char)output_seq2tmp_excepted[i]) {
      printf("ERROR: output_seq2tmp[%d] = %d, expected %d\n", i, output_seq2tmp_data[i], (unsigned char)output_seq2tmp_excepted[i]);
      REG_WRITE(0x1fff4000 + 0x0, 0x18); // gpio3 4 pluse
      REG_WRITE(0x1fff4000 + 0x0, 0x0); // gpio3 4 pluse
    }
  }
  unsigned char* output_tbs_data = (unsigned char*)pop_fifo(&tbs_s.fifo);
  for (int i = 0; i < 4; i++) {
    if (output_tbs_data[i] != (unsigned char)output_tbs_excepted[i]) {
      printf("ERROR: output_tbs[%d] = %d, expected %d\n", i, output_tbs_data[i], (unsigned char)output_tbs_excepted[i]);
      REG_WRITE(0x1fff4000 + 0x0, 0x18); // gpio3 4 pluse
      REG_WRITE(0x1fff4000 + 0x0, 0x0); // gpio3 4 pluse
    }
  }
  unsigned char* output_pdsch_llr_data = (unsigned char*)pop_fifo(&pdsch_llr.fifo);
  for (int i = 0; i < 4; i++) {
    if (output_pdsch_llr_data[i] != (unsigned char)output_pdsch_llr_excepted[i]) {
      printf("ERROR: output_pdsch_llr[%d] = %d, expected %d\n", i, output_pdsch_llr_data[i], (unsigned char)output_pdsch_llr_excepted[i]);
      REG_WRITE(0x1fff4000 + 0x0, 0x18); // gpio3 4 pluse
      REG_WRITE(0x1fff4000 + 0x0, 0x0); // gpio3 4 pluse
    }
  }

// /////////////////////////////////////////////////////////////////////////

  REG_WRITE(0x1fff4000 + 0x0, 0x8); // gpio3 pluse
  REG_WRITE(0x1fff4000 + 0x0, 0x0); // gpio3 pluse

  while (1) {};
